// chartLibrary.js
// Animated chart cards for the Funding Finder results screen.
// No exports — loaded as a plain <script> tag before funding-finder.html's own script.
// Depends on globalInsights.js for parseMoneyString().

function getFundingChartHtml(matchedProducts, userState) {
  var charts = [];
  var hasInvoice = matchedProducts.indexOf('invoice') !== -1;
  var hasTrade   = matchedProducts.indexOf('trade')   !== -1;
  var hasMca     = matchedProducts.indexOf('mca')     !== -1;
  var hasDebt    = matchedProducts.indexOf('debtRecovery') !== -1;
  var turnover   = (userState && userState.turnover)  || '';
  var payDays    = (userState && userState.paymentTermsDays) || '30';
  var amount     = (userState && userState.fundingAmount)    || '';
  var industry   = ((userState && userState.industry) || '').toLowerCase();
  var isConstr   = industry.indexOf('construction') !== -1;
  var fa         = (userState && userState.flowAnswers) || {};
  var isAcq      = fa.acquisition === 'Yes' || fa.acquisition === "Not right now but it's on my radar";

  if (isAcq) {
    charts.push(_fc_acquisitionChart());
  } else if (hasInvoice && hasTrade) {
    charts.push(_fc_combinedCycle());
  } else if (hasInvoice) {
    var _tv = (typeof parseMoneyString === 'function') ? (parseMoneyString(String(turnover || '')) || 0) : 0;
    var _barrier = String((userState && userState.barrierDetails) || '').toLowerCase();
    var _tiedIn = _barrier.indexOf('contract') !== -1 || _barrier.indexOf('tied') !== -1 ||
                  _barrier.indexOf('stuck') !== -1    || _barrier.indexOf('notice') !== -1 ||
                  _barrier.indexOf('exit') !== -1     || _barrier.indexOf('fee') !== -1;
    if (_tv < 250000 || _tiedIn) {
      charts.push(_fc_spotFundingChart());
    } else {
      charts.push(_fc_invoiceOnly(turnover, payDays, isConstr));
    }
  } else if (hasTrade) {
    charts.push(_fc_tradeOnly());
  } else if (hasMca) {
    charts.push(_fc_mcaChart());
  } else if (hasDebt) {
    charts.push(_fc_debtChart());
  } else {
    charts.push(_fc_repaymentChart(amount));
  }

  if (matchedProducts.length >= 2) {
    charts.push(_fc_productFitChart(matchedProducts));
  }

  if (!charts.length) return '';
  return '<div class="fc-section">' + charts.join('') + '</div>';
}

// ===== PRODUCT FIT CHART (dynamic) =====
function _fc_productFitChart(matchedProducts) {
  var labels = {
    invoice:'Invoice Finance', trade:'Trade Finance', asset:'Asset Finance',
    loan:'Business Loan', revolving:'Revolving Credit', mca:'Merchant Cash Advance',
    property:'Commercial Property', fx:'FX & International Payments', rd:'R\u0026D Tax Credits',
    debtRecovery:'Debt Recovery', mbo:'Acquisition Finance', bridging:'Bridging Finance', shariah:'Shariah Finance'
  };
  var scores = [90, 78, 66, 54, 42];
  var top = matchedProducts.slice(0, 5);
  var svgH = top.length * 50 + 30;
  var rows = '';
  top.forEach(function(p, i) {
    var label = labels[p] || p;
    var score = scores[i] !== undefined ? scores[i] : 42;
    var w     = Math.round((score / 100) * 340);
    var y     = 10 + i * 50;
    var d1 = parseFloat((0.10 + i * 0.15).toFixed(2));
    var d2 = parseFloat((0.20 + i * 0.15).toFixed(2));
    var d3 = parseFloat((1.10 + i * 0.15).toFixed(2));
    rows +=
      '<text class="fade-in" style="animation-delay:' + d1 + 's" x="20" y="' + (y+14) + '" fill="#f4f0ff" font-size="13">' + label + '</text>' +
      '<rect x="196" y="' + y + '" width="344" height="20" rx="10" fill="rgba(255,255,255,0.08)"/>' +
      '<rect class="grow-right" style="animation-delay:' + d2 + 's" x="196" y="' + y + '" width="' + w + '" height="20" rx="10" fill="url(#fc-fitGold)"/>' +
      '<text class="fade-in" style="animation-delay:' + d3 + 's" x="550" y="' + (y+14) + '" fill="#ffc499" font-size="12" font-weight="600" text-anchor="end">' + score + '%</text>';
  });
  return '<div class="fc-card fc-fit-card">' +
    '<div class="fc-tag">Matched products \u2014 fit ranking</div>' +
    '<h2 class="fc-heading">How well each option fits your profile</h2>' +
    '<div class="chart-wrap">' +
    '<svg viewBox="0 0 570 ' + svgH + '" aria-label="Product fit ranking">' +
    rows +
    '<defs><linearGradient id="fc-fitGold" x1="0" y1="0" x2="1" y2="0">' +
    '<stop offset="0%" stop-color="#ee6a1a"/><stop offset="100%" stop-color="#cc44ff"/>' +
    '</linearGradient></defs></svg></div></div>';
}

// ===== REPAYMENT COMPARISON (dynamic) =====
function _fc_repaymentChart(amountStr) {
  var principal = (typeof parseMoneyString === 'function') ? (parseMoneyString(String(amountStr || '')) || 50000) : 50000;
  var rate = 0.08 / 12;
  function mp(n) {
    var f = rate * Math.pow(1+rate,n) / (Math.pow(1+rate,n)-1);
    return Math.round(principal * f / 25) * 25;
  }
  var p3 = mp(36), p4 = mp(48), p5 = mp(60);
  var maxP  = Math.ceil(Math.max(p3, p4, p5) / 200) * 200;
  var scale = 180 / maxP;
  function barY(v) { return Math.round(220 - v * scale); }
  function barH(v) { return Math.round(v * scale); }
  function fmt(v) { return '\u00a3' + v.toLocaleString('en-GB'); }
  return '<div class="fc-card fc-fit-card">' +
    '<div class="fc-tag">Business Loan \u00b7 Asset Finance</div>' +
    '<h2 class="fc-heading">Monthly repayment by term \u2014 ' + fmt(principal) + '</h2>' +
    '<div class="chart-wrap">' +
    '<svg viewBox="0 0 600 278" aria-label="Monthly repayment comparison">' +
    '<g stroke="rgba(255,255,255,0.06)" stroke-width="1"><line x1="60" y1="40" x2="580" y2="40"/><line x1="60" y1="130" x2="580" y2="130"/><line x1="60" y1="220" x2="580" y2="220"/></g>' +
    '<g fill="rgba(255,255,255,0.4)" font-size="11" text-anchor="end">' +
    '<text x="52" y="44">' + fmt(maxP) + '</text>' +
    '<text x="52" y="134">' + fmt(maxP/2) + '</text>' +
    '<text x="52" y="224">\u00a30</text>' +
    '</g>' +
    '<rect class="grow-up" style="animation-delay:0.1s" x="110" y="' + barY(p3) + '" width="90" height="' + barH(p3) + '" rx="6" fill="url(#fc-goldGrad)"/>' +
    '<text class="slide-up" style="animation-delay:0.7s" x="155" y="' + Math.max(barY(p3)-6,16) + '" fill="#fff" font-size="14" font-weight="600" text-anchor="middle">' + fmt(p3) + '</text>' +
    '<text class="fade-in" style="animation-delay:0.9s" x="155" y="242" fill="rgba(255,255,255,0.6)" font-size="12" text-anchor="middle">3 years</text>' +
    '<rect class="grow-up" style="animation-delay:0.25s" x="255" y="' + barY(p4) + '" width="90" height="' + barH(p4) + '" rx="6" fill="url(#fc-goldGrad)"/>' +
    '<text class="slide-up" style="animation-delay:0.85s" x="300" y="' + Math.max(barY(p4)-6,16) + '" fill="#fff" font-size="14" font-weight="600" text-anchor="middle">' + fmt(p4) + '</text>' +
    '<text class="fade-in" style="animation-delay:1.05s" x="300" y="242" fill="rgba(255,255,255,0.6)" font-size="12" text-anchor="middle">4 years</text>' +
    '<rect class="grow-up" style="animation-delay:0.4s" x="400" y="' + barY(p5) + '" width="90" height="' + barH(p5) + '" rx="6" fill="url(#fc-goldGrad)"/>' +
    '<text class="slide-up" style="animation-delay:1.0s" x="445" y="' + Math.max(barY(p5)-6,16) + '" fill="#fff" font-size="14" font-weight="600" text-anchor="middle">' + fmt(p5) + '</text>' +
    '<text class="fade-in" style="animation-delay:1.2s" x="445" y="242" fill="rgba(255,255,255,0.6)" font-size="12" text-anchor="middle">5 years</text>' +
    '<text class="fade-in" style="animation-delay:1.6s" x="300" y="266" fill="rgba(255,255,255,0.35)" font-size="10" text-anchor="middle">Indicative at 8% p.a. \u2014 actual rate confirmed at credit stage</text>' +
    '<defs><linearGradient id="fc-goldGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#f5c674"/><stop offset="100%" stop-color="#f5a623"/></linearGradient></defs>' +
    '</svg></div></div>';
}

// ===== INVOICE ONLY (animated cycle) =====
function _fc_invoiceOnly(turnover, payDays, isConstr) {
  var tv   = (typeof parseMoneyString === 'function') ? (parseMoneyString(String(turnover || '')) || 0) : 0;
  var days = parseInt(payDays) || 30;
  var rate = isConstr ? 0.60 : 0.90;
  var advAmt     = tv ? (Math.round(((tv/12)/30) * days * rate / 1000) * 1000) : 0;
  var debtorBook = tv ? (Math.round(((tv/12)/30) * days         / 1000) * 1000) : 0;

  var heroHtml = advAmt
    ? '<div class="if-hero"><div class="if-amount">£' + advAmt.toLocaleString('en-GB') + '</div>'
      + '<div class="if-sub">could be in your account <b>within 24 hours</b></div></div>'
    : '';

  var step1p = debtorBook
    ? '£' + debtorBook.toLocaleString('en-GB') + ' on ' + days + '-day terms'
    : 'Your invoice value';
  var step2p = advAmt
    ? '£' + advAmt.toLocaleString('en-GB') + ' in your account today'
    : 'Up to 90% in your account today';

  var pill1 = isConstr
    ? '<span class="if-pill if-o"><span class="if-dot"></span>50–70% advance typical</span>'
    : '<span class="if-pill if-o"><span class="if-dot"></span>90% advanced upfront</span>';

  var step2heading = isConstr ? 'Get your advance' : 'Get 90% now';

  var constrNote = isConstr
    ? '<p class="if-constr-note">Because construction debt is often contractual in nature'
      + ' (retentions, stage payments, applications for payment), advances are typically lower'
      + ' — often in the 50–70% range, and some lenders assess these case by case.</p>'
    : '';

  var flowCap = isConstr
    ? '<b>50–70% of eligible invoice value, released early</b>'
    : '<b>90% of every invoice, 30 days early</b>';

  return '<div class="fc-card if-card">'
    + '<span class="if-eyebrow"><span class="if-dot"></span>Invoice Finance · Standalone</span>'
    + heroHtml
    + '<p class="if-lead"><span class="if-pct">87%</span> of invoice finance users say it let them grow faster. Unlock the cash already tied up in your unpaid invoices — without waiting 30, 60 or 90 days to get paid.</p>'
    + constrNote
    + '<div class="if-pills">'
    +   pill1
    +   '<span class="if-pill if-p"><span class="if-dot"></span>30 days faster</span>'
    +   '<span class="if-pill if-o"><span class="if-dot"></span>Same-day cash</span>'
    +   '<span class="if-pill if-p"><span class="if-dot"></span>0.5–3% typical fee</span>'
    + '</div>'
    + '<div class="if-flow">'
    +   '<div class="if-step"><div class="if-n">1</div><h4>Raise invoice</h4><p>' + step1p + '</p></div>'
    +   '<div class="if-step"><div class="if-n">2</div><h4>' + step2heading + '</h4><p>' + step2p + '</p></div>'
    +   '<div class="if-step"><div class="if-n">3</div><h4>Customer pays</h4><p>Balance released, minus fee</p></div>'
    + '</div>'
    + '<p class="if-flow-cap">Result: ' + flowCap + '</p>'
  + '</div>';
}

