<!-- DEBT COLLECTOR (bottom-centre) -->\n        <g class=\"fade-in\" style=\"animation-delay:0.9s\" transform=\"translate(370,495)\">\n          <circle r=\"44\" fill=\"rgba(196,78,199,0.10)\" stroke=\"rgba(196,78,199,0.45)\" stroke-width=\"1.5\"/>\n          <circle cx=\"-2\" cy=\"-18\" r=\"7\" fill=\"none\" stroke=\"#c44ec7\" stroke-width=\"2.2\"/>\n          <line x1=\"-2\" y1=\"-11\" x2=\"-2\" y2=\"8\" stroke=\"#c44ec7\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n          <line x1=\"-12\" y1=\"-3\" x2=\"9\" y2=\"-3\" stroke=\"#c44ec7\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n          <line x1=\"-2\" y1=\"8\" x2=\"-8\" y2=\"20\" stroke=\"#c44ec7\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n          <line x1=\"-2\" y1=\"8\" x2=\"4\" y2=\"20\" stroke=\"#c44ec7\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n          <rect x=\"11\" y=\"-1\" width=\"12\" height=\"9\" rx=\"0.5\" fill=\"#c44ec7\"/>\n          <rect x=\"11\" y=\"-4\" width=\"6\" height=\"3\" fill=\"#c44ec7\"/>\n          <text y=\"58\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"12\" font-weight=\"700\">DEBT COLLECTOR</text>\n          <text y=\"71\" text-anchor=\"middle\" fill=\"rgba(255,255,255,0.55)\" font-size=\"9\">No-win-no-fee specialist</text>\n        </g>\n\n        <!-- Step 2: case file You \u2192 Collector -->\n        <g transform=\"translate(180,280)\">\n          <g class=\"flow-icon\" style=\"--dx:190px; --dy:215px; animation-delay:2.1s;\">\n            <rect x=\"-13\" y=\"-8\" width=\"26\" height=\"18\" rx=\"2\" fill=\"#fff\" stroke=\"#c44ec7\" stroke-width=\"1.5\"/>\n            <path d=\"M -13,-8 L -7,-13 L 1,-13 L 1,-8 Z\" fill=\"#c44ec7\"/>\n            <text y=\"4\" text-anchor=\"middle\" fill=\"#c44ec7\" font-size=\"6\" font-weight=\"700\">CASE FILE</text>\n          </g>\n        </g>\n\n        <!-- Step 3: legal notice Collector \u2192 Debtor -->\n        <g transform=\"translate(370,495)\">\n          <g class=\"flow-icon\" style=\"--dx:190px; --dy:-215px; animation-delay:3.7s;\">\n            <rect x=\"-15\" y=\"-10\" width=\"30\" height=\"20\" rx=\"1\" fill=\"#fff\" stroke=\"#c44ec7\" stroke-width=\"1.5\"/>\n            <text y=\"0\" text-anchor=\"middle\" fill=\"#c44ec7\" font-size=\"6\" font-weight=\"700\">LEGAL NOTICE</text>\n            <line x1=\"-10\" y1=\"4\" x2=\"10\" y2=\"4\" stroke=\"#c44ec7\" stroke-width=\"0.8\"/>\n            <circle cx=\"-10\" cy=\"-6\" r=\"2.5\" fill=\"none\" stroke=\"#c44ec7\" stroke-width=\"0.8\"/>\n          </g>\n        </g>\n\n        <!-- Step 4: Debtor pays Collector -->\n        <g transform=\"translate(560,280)\">\n          <g class=\"flow-icon\" style=\"--dx:-190px; --dy:215px; animation-delay:5.3s;\">\n            <circle r=\"16\" fill=\"#6ee7b7\" stroke=\"#fff\" stroke-width=\"2\"/>\n            <text y=\"5\" text-anchor=\"middle\" fill=\"#1a0a2e\" font-size=\"14\" font-weight=\"700\">\u00a3</text>\n          </g>\n        </g>\n\n        <!-- Step 5: Collector \u2192 You (balance) -->\n        <g transform=\"translate(370,495)\">\n          <g class=\"flow-icon\" style=\"--dx:-190px; --dy:-215px; animation-delay:6.9s;\">\n            <circle r=\"15\" fill=\"#f5a623\" stroke=\"#fff\" stroke-width=\"2\"/>\n            <text y=\"5\" text-anchor=\"middle\" fill=\"#1a0a2e\" font-size=\"14\" font-weight=\"700\">\u00a3</text>\n          </g>\n        </g>\n\n        <!-- Captions -->\n        <g class=\"step-txt\" style=\"animation-delay:0.5s\">\n          <text x=\"360\" y=\"370\" text-anchor=\"middle\" fill=\"#f5c674\" font-size=\"10\" font-weight=\"600\" letter-spacing=\"2\">STEP 1</text>\n          <text x=\"360\" y=\"393\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"14\" font-weight=\"600\">\u00a325,000 stuck at 90+ days</text>\n          <text x=\"360\" y=\"411\" text-anchor=\"middle\" fill=\"rgba(255,255,255,0.6)\" font-size=\"11\">About to be written off as bad debt</text>\n        </g>\n        <g class=\"step-txt\" style=\"animation-delay:2.1s\